55: static apr_status_t
56: iconv_getpathname(char *buffer, const char *dir, const char *name, apr_pool_t *ctx)
57: {
58:         apr_status_t rv;
59: 	apr_finfo_t sb;
60: 
61: 	apr_snprintf(buffer, APR_PATH_MAX, "%s/%s.so", dir, name);
62:         rv = apr_stat(&sb, buffer, APR_FINFO_TYPE, ctx);
63: #ifdef API_HAVE_CHARSET_ALIAS_TABLE
64:         /* If we didn't find the file, try again after looking in
65:            the charset alias mapping table. */
66:         if (rv || sb.filetype != APR_REG) {
67:             const char *alias = charset_alias_find(name);
68:             if (alias) {
69:                 apr_snprintf(buffer, APR_PATH_MAX, "%s/%s.so", dir, alias);
70:                 rv = apr_stat(&sb, buffer, APR_FINFO_TYPE, ctx);
71:             }
72:         }
73: #endif /* API_HAVE_CHARSET_ALIAS_TABLE */
74:         if (!rv && sb.filetype != APR_REG)
75:             rv = APR_EINVAL;
76: 
77:         return rv;
78: }
