80: static apr_status_t
81: iconv_getpath(char *buf, const char *name, apr_pool_t *ctx)
82: {
83: 	char buffer[APR_PATH_MAX];
84:         apr_array_header_t *pathelts;
85:         apr_pool_t *subpool;
86:         apr_status_t status;
87: 	char *ptr;
88: 
89:         status = apr_pool_create(&subpool, ctx);
90:         if (status)
91:             return status;
92: 
93: 	if (apr_tolower(name[0]) == 'x' && name[1] == '-')
94: 		name += 2;
95:         ptr = buffer;
96:         while (0 != (*ptr++ = apr_tolower(*name++)))
97:             ;
98: 
99:         /* Fall back on APR_ICONV_PATH if APR_ICONVn_PATH isn't set...
100:          * TODO: Drop support for "APR_ICONV_PATH" in apr-iconv 2.0
101:          */
102:         if ((!apr_env_get(&ptr, APR_ICONV_PATH, subpool)
103:              || (!apr_env_get(&ptr, "APR_ICONV_PATH", subpool)))
104:             && !apr_filepath_list_split(&pathelts, ptr, subpool))
105:         {
106:             int i;
107:             char **elts = (char **)pathelts->elts;
108:             for (i = 0; i < pathelts->nelts; ++i)
109:             {
110:                 if (iconv_getpathname(buf, elts[i], buffer, subpool) == 0)
111:                 {
112:                     apr_pool_destroy(subpool);
113:                     return APR_SUCCESS;
114:                 }
115:             }
116:         }
117: 
118:         status = iconv_getpathname(buf, ICONV_DEFAULT_PATH, buffer, subpool);
119:         apr_pool_destroy(subpool);
120:         return status;
121: }
