123: static int
124: iconv_dlopen(const char *name, const char *symbol, void **hpp, void **dpp, apr_pool_t *ctx)
125: {
126: 	apr_dso_handle_t *handle;
127: 	void *data;
128: 
129: 	/* dlopen */
130: 	if (apr_dso_load(&handle, name, ctx) != APR_SUCCESS) {
131: 		return EINVAL;
132: 	}
133: 	/* dlsym */
134: 	if ( apr_dso_sym(&data, handle, symbol) == APR_SUCCESS) {
135: 		*hpp = handle;
136: 		*dpp = data;
137: 		return 0;
138: 	}
139: 	apr_dso_unload(handle);
140: 	return EINVAL;
141: }
