143: API_DECLARE_NONSTD(int)
144: apr_iconv_mod_load(const char *modname, int modtype, const void *args,
145: 	struct iconv_module **modpp, apr_pool_t *ctx)
146: {
147: 	struct iconv_module_desc *mdesc;
148: 	struct iconv_module *mod, *depmod;
149: 	const struct iconv_module_depend *depend;
150: 	char buffer[APR_PATH_MAX];
151: 	void *handle;
152: 	int error;
153: 
154: 	if (iconv_getpath(buffer, modname, ctx) != 0)
155: 		return EINVAL;
156: 
157: 	error = iconv_dlopen(buffer, "iconv_module", &handle, (void**)&mdesc, ctx);
158: 	if (error)
159: 		return error;
160: 	if (modtype != ICMOD_ANY && mdesc->imd_type != modtype) {
161: 		apr_dso_unload(handle);
162: 		return APR_EFTYPE;
163: 	}
164: 	mod = malloc(sizeof(*mod));
165: 	if (mod == NULL) {
166: 		apr_dso_unload(handle);
167: 		return ENOMEM;
168: 	}
169: 	memset(mod, 0, sizeof(*mod));
170: 	mod->im_handle = handle;
171: 	mod->im_desc = mdesc;
172: 	mod->im_args = args;
173: 	depend = mdesc->imd_depend;
174: 	if (depend) {
175: 		while (depend->md_name) {
176: 			error = apr_iconv_mod_load(depend->md_name, 
177: 			    depend->md_type, NULL, &depmod, ctx);
178: 			if (error)
179: 				goto bad;
180: 			depmod->im_depdata = depend->md_data;
181: 			depmod->im_next = mod->im_deplist;
182: 			mod->im_deplist = depmod;
183: 			depend++;
184: 		}
185: 	}
186: 	error = ICONV_MOD_DYN_LOAD(mod,ctx);
187: 	if (error)
188: 		goto bad;
189: 	depmod = mod->im_deplist;
190: 	while (depmod) {
191: 		mod->im_depcnt++;
192: 		depmod = depmod->im_next;
193: 	}
194: 	error = ICONV_MOD_LOAD(mod,ctx);
195: 	if (error)
196: 		goto bad;
197: 	mod->im_flags |= ICMODF_LOADED;
198: 	*modpp = mod;
199: 	return 0;
200: bad:
201: 	apr_iconv_mod_unload(mod,ctx);
202: 	return error;
203: }
204: 
205: API_DECLARE_NONSTD(int)
206: apr_iconv_mod_unload(struct iconv_module *mod, apr_pool_t *ctx)
207: {
208: 	struct iconv_module *deplist, *tmp;
209: 	int error = 0;
210: 
211: 	if (mod == NULL)
212: 		return -1;
213: 	if (mod->im_flags & ICMODF_LOADED)
214: 		error = ICONV_MOD_UNLOAD(mod,ctx);
215: 	error = ICONV_MOD_DYN_UNLOAD(mod,ctx);
216: 	deplist = mod->im_deplist;
217: 	while (deplist) {
218: 		tmp = deplist->im_next;
219: 		apr_iconv_mod_unload(deplist,ctx);
220: 		deplist = tmp;
221: 	}
222: 	if (mod->im_handle != NULL)
223: 		if (apr_dso_unload(mod->im_handle) != APR_SUCCESS)
224: 			error = APR_EINVAL;
225: 	free(mod);
226: 	return error;
227: }
