221: static ucs_t
222: cvt_iso2ucs(const struct iconv_ccs_desc *ccs, const unsigned char **inbuf,
223: 	apr_size_t *inbytesleft, int prefix_type)
224: {
225: 	apr_size_t bytes = ccs->nbits > 8 ? 2 : 1;
226: 	ucs_t ch = **inbuf;
227: 
228: 	if (*inbytesleft < bytes)
229: 		return UCS_CHAR_NONE;	/* Not enough bytes in the input buffer */
230: 	if (bytes == 2)
231: 		ch = (ch << 8) | *(++(*inbuf));
232: 	(*inbuf)++;
233: 	(*inbytesleft) -= bytes;
234: 	if (ch & 0x8080)
235: 		return UCS_CHAR_INVALID;
236: 	if (prefix_type == ICONV_PREFIX_CHAR && !is_7_14bit(ccs))
237: 		ch |= (bytes == 2) ? 0x8080 : 0x80;
238: 	return ICONV_CCS_CONVERT_TO_UCS(ccs, ch);
