276: 			if (len) {
277: 				if (len + 1 > left)
278: 					return UCS_CHAR_NONE;
279: 				if (memcmp(ptr,
280: 				    iso_shift[ccsattr->shift].sequence, len) == 0) {
281: 					if (iso_shift[ccsattr->shift].prefix_type != ICONV_PREFIX_CHAR)
282: 						iso_state->shift_index = ccsattr->shift;
